const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.0060, 40.7128]); // New York City (Manhattan)

  const date = '2023-08-09';
  const utcOffsetHours = -4; // NYC is EDT (UTC-4) on Aug 9, 2023

  // Convert local times to UTC
  // Window 1: 2:00 PM - 3:00 PM EDT (14:00 - 15:00 EDT)
  const startTime1_utc = ee.Date(date).advance(14 + utcOffsetHours, 'hour'); // 10:00 UTC
  const endTime1_utc = ee.Date(date).advance(15 + utcOffsetHours, 'hour');   // 11:00 UTC

  // Window 2: 5:00 PM - 6:00 PM EDT (17:00 - 18:00 EDT)
  const startTime2_utc = ee.Date(date).advance(17 + utcOffsetHours, 'hour'); // 13:00 UTC
  const endTime2_utc = ee.Date(date).advance(18 + utcOffsetHours, 'hour');   // 14:00 UTC

  const scale = 1000; // Use a reasonable scale for regional analysis

  // Function to process NO2 data for a given time window
  const processNO2 = (startTime, endTime, label) => {
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterBounds(nyc)
      .filterDate(startTime, endTime)
      .select('tropospheric_NO2_column_number_density');

    const collectionSize = collection.size().getInfo();
    console.log(`${label} Images: ${collectionSize}`);

    if (collectionSize === 0) {
      return { value: null, pixels: 0, status: 'C1' };
    }

    // Apply quality mask: qa_value > 0.75
    collection = collection.map(image => image.updateMask(image.select('qa_value').gt(0.75)));

    const image = collection.median(); // Use median to get a representative value if multiple images

    if (image.bandNames().length().getInfo() === 0) {
        return { value: null, pixels: 0, status: 'C2' }; // No bands left after filtering
    }

    // Check for valid pixels
    const pixelCount = image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: nyc,
      scale: scale,
      maxPixels: 1e9
    }).get('tropospheric_NO2_column_number_density').getInfo();

    if (pixelCount === 0) {
      return { value: null, pixels: 0, status: 'C2' };
    }

    // Calculate mean NO2 concentration
    const meanNO2 = image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: nyc,
      scale: scale,
      maxPixels: 1e9
    }).get('tropospheric_NO2_column_number_density').getInfo();

    if (meanNO2 === null || isNaN(meanNO2)) {
      return { value: null, pixels: pixelCount, status: 'C3' };
    }

    return { value: meanNO2, pixels: pixelCount, status: 'OK' };
  };

  // Process data for both time windows
  const result1 = processNO2(startTime1_utc, endTime1_utc, '2:00-3:00 PM EDT');
  const result2 = processNO2(startTime2_utc, endTime2_utc, '5:00-6:00 PM EDT');

  // Evaluate results
  if (result1.status !== 'OK' && result1.status !== 'C1') { // C2 or C3
    console.log(`Error processing 2:00-3:00 PM data: ${result1.status}`);
    console.log(`<answer>${result1.status}</answer>`);
    return;
  }
  if (result2.status !== 'OK' && result2.status !== 'C1') { // C2 or C3
    console.log(`Error processing 5:00-6:00 PM data: ${result2.status}`);
    console.log(`<answer>${result2.status}</answer>`);
    return;
  }

  // Handle C1 cases
  if (result1.status === 'C1' && result2.status === 'C1') {
    console.log("<answer>C1</answer>");
    return;
  }
  // If one window has data and the other doesn't, we can't compare effectively.
  // Sentinel-5P generally has a single overpass per day, which would fall into only one or neither of these windows.
  if (result1.status === 'C1' || result2.status === 'C1') {
      console.log("Not enough data for a complete comparison from both time windows.");
      console.log("<answer>C1</answer>");
      return;
  }

  // Handle C2/C3 if they were not caught earlier for OK status
  if (result1.status === 'C2' || result2.status === 'C2') {
      console.log("<answer>C2</answer>");
      return;
  }
  if (result1.status === 'C3' || result2.status === 'C3') {
      console.log("<answer>C3</answer>");
      return;
  }

  // Final comparison
  const no2_pm2_3 = result1.value;
  const no2_pm5_6 = result2.value;

  console.log(`2:00-3:00 PM EDT NO2: ${no2_pm2_3 !== null ? no2_pm2_3.toFixed(9) : 'N/A'} (Pixels: ${result1.pixels})`);
  console.log(`5:00-6:00 PM EDT NO2: ${no2_pm5_6 !== null ? no2_pm5_6.toFixed(9) : 'N/A'} (Pixels: ${result2.pixels})`);

  if (no2_pm2_3 > no2_pm5_6) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
